const now = new Date();
// Chuyển sang giờ Việt Nam (UTC+7)
const hour = (now.getUTCHours() + 7) % 24;

let topic = 'focus';
let topicName = 'Tập Trung Sâu & Trị Sương Mù Não';

if (hour >= 18 || hour < 5) {
  topic = 'habit';
  topicName = 'Xây Dựng Thói Quen & Kỷ Luật Không Gồng';
}

return [{
  json: {
    topic: topic,
    topicName: topicName,
    hour: hour,
    executedAt: now.toISOString()
  }
}];

const res = $input.first().json;
const topicData = $('Xác Định Chủ Đề (Focus/Habit)').first().json;

const isSuccess = res.status === 'success';
const statusIcon = isSuccess ? '✅ THÀNH CÔNG' : '⚠️ CẦN KIỂM TRA';
const webUrl = res.website_url || 'https://traicainghien.com/bai-viet';

let msg = `🚀 <b>MÂY N8N — FLOW 03 ĐÃ XUẤT BẢN THÀNH CÔNG!</b>\n\n`;
msg += `📌 <b>Trạng thái:</b> ${statusIcon}\n`;
msg += `🏷 <b>Chủ đề:</b> [${topicData.topicName}]\n`;
msg += `🌐 <b>Website:</b> <a href="${webUrl}">${webUrl}</a>\n`;
msg += `📘 <b>Fanpage:</b> <a href="https://facebook.com/traicainghien">Trại Cai Nghiện Fanpage</a>\n`;
msg += `📢 <b>Telegram Channel:</b> @traicainghiendaily\n\n`;
msg += `🌱 <i>Bộ máy tự động n8n đã hoàn tất toàn bộ chu trình cào video, viết bài, deploy web và phát sóng đa kênh!</i>`;

return [{
  json: {
    chat_id: '488901419',
    text: msg,
    parse_mode: 'HTML'
  }
}];
